import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import API_BASE_URL from "../config";
import "../styles/UserPages.css";

const AllListings = () => {
  const userId = sessionStorage.getItem("userId");
  const [listings, setListings] = useState([]);
  const [favorites, setFavorites] = useState([]);
  const [users, setUsers] = useState([]);
  const [showUsers, setShowUsers] = useState(false);
  const [showReportForm, setShowReportForm] = useState(false);
  const [reportUsername, setReportUsername] = useState("");
  const [reportReason, setReportReason] = useState("");

  useEffect(() => {
    // Load all listings with usernames
    fetch(`${API_BASE_URL}/api/listings`)
      .then((res) => res.json())
      .then((data) => {
        const filtered = data.filter(
          (item) => String(item.user_id) !== String(userId) && !item.sold
        );
        setListings(filtered);
      });

    // Load all users
    fetch(`${API_BASE_URL}/api/users`)
      .then((res) => res.json())
      .then((data) => setUsers(data));

    // Load user's favorites
    if (userId) {
      fetch(`${API_BASE_URL}/api/favorites/user/${userId}`)
        .then((res) => res.json())
        .then((data) => setFavorites(data.map((fav) => fav.id)));
    }
  }, [userId]);

  const handleBuy = async (item) => {
    const res = await fetch(`${API_BASE_URL}/api/cart`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ ...item, user_id: userId }),
    });

    res.ok ? alert("Item added to cart!") : alert("Failed to add to cart.");
  };

  const handleAddFavorite = async (itemId) => {
    const res = await fetch(`${API_BASE_URL}/api/favorites`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ user_id: userId, listing_id: itemId }),
    });

    if (res.ok) {
      setFavorites((prev) => [...prev, itemId]);
      alert("Favorited!");
    }
  };

  const handleFlag = async (listingId) => {
    const reason = prompt("Why are you flagging this listing?");
    await fetch(`${API_BASE_URL}/api/listings/flag`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ user_id: userId, listing_id: listingId, reason }),
    });
    alert("Listing flagged.");
  };

  const submitReport = async () => {
    if (!reportUsername || !reportReason) return alert("Fill in both fields.");

    const res = await fetch(`${API_BASE_URL}/api/users/report`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        username: reportUsername,
        reason: reportReason,
        reporter_id: userId,
      }),
    });

    if (res.ok) {
      alert("Report submitted.");
      setShowReportForm(false);
      setReportUsername("");
      setReportReason("");
    } else {
      alert("Failed to submit report.");
    }
  };

  return (
    <div className="dashboard-wrapper" style={{ minHeight: "100vh", display: "flex", flexDirection: "column" }}>
      <Navbar />
      <main className="dashboard-main" style={{ flex: 1, padding: "32px 48px" }}>
        <h2 style={{ textAlign: "center", marginBottom: "20px" }}>Explore All Listings</h2>

        <div style={{ display: "flex", justifyContent: "center", gap: "16px", marginBottom: "30px" }}>
          <button onClick={() => setShowUsers(!showUsers)} className="toggle-btn">👥 View Users</button>
          <button onClick={() => setShowReportForm(true)} className="toggle-btn">🚨 Report User</button>
        </div>

        {showUsers && (
          <div style={{ marginBottom: "30px", textAlign: "center" }}>
            <h4>Registered Users</h4>
            <ul style={{ listStyle: "none", padding: 0 }}>
              {users.map((user) => (
                <li key={user.id}>{user.username}</li>
              ))}
            </ul>
          </div>
        )}

        {showReportForm && (
          <div style={{ maxWidth: "400px", margin: "0 auto 40px", padding: "20px", border: "1px solid #ccc", borderRadius: "8px", background: "#f9f9f9" }}>
            <h4>Report a User</h4>
            <input
              type="text"
              placeholder="Username"
              value={reportUsername}
              onChange={(e) => setReportUsername(e.target.value)}
              style={{ width: "100%", padding: "8px", marginBottom: "10px" }}
            />
            <textarea
              placeholder="Reason"
              value={reportReason}
              onChange={(e) => setReportReason(e.target.value)}
              style={{ width: "100%", padding: "8px", height: "80px" }}
            />
            <button className="submit-btn" onClick={submitReport}>Submit Report</button>
            <button className="cancel-btn" onClick={() => setShowReportForm(false)}>Cancel</button>
          </div>
        )}

        <div className="item-grid">
          {listings.length > 0 ? (
            listings.map((item) => (
              <div className="item-card" key={item.id}>
                <div className="image-placeholder">
                  {item.image ? <img src={item.image} alt={item.title} /> : <span>No Image</span>}
                </div>
                <h4>{item.title}</h4>
                <p>{item.description}</p>
                <p><strong>Seller:</strong> {item.username}</p>
                <p><strong>Condition:</strong> {item.condition}</p>
                <p><strong>Price:</strong> ${parseFloat(item.price).toFixed(2)}</p>
                <div className="listing-actions">
                  <button onClick={() => handleBuy(item)}>Buy</button>
                  <button onClick={() => handleAddFavorite(item.id)} disabled={favorites.includes(item.id)}>
                    {favorites.includes(item.id) ? "❤️ Favorited" : "🤍 Favorite"}
                  </button>
                  <button onClick={() => handleFlag(item.id)}>🏴 Flag</button>
                </div>
              </div>
            ))
          ) : (
            <p style={{ textAlign: "center" }}>No listings available from other users.</p>
          )}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default AllListings;
